cat > src/lib/postmark.ts <<'EOF'
import { ServerClient } from "postmark";

let client: ServerClient | undefined;

// Created lazily so importing this module (e.g. during `next build`) doesn't require the token.
export function getPostmark(): ServerClient {
  const token = process.env.POSTMARK_SERVER_TOKEN;
  if (!token) throw new Error("POSTMARK_SERVER_TOKEN is not set");
  return (client ??= new ServerClient(token));
}
EOF
cat > src/lib/email.ts <<'EOF'
import { getPostmark } from "@/lib/postmark";

type Recipient = { email: string; name: string };

const escapeHtml = (s: string) =>
  s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

const appUrl = () => process.env.APP_URL ?? "http://localhost:3000";

// Email must never break the request that triggered it, so failures are logged, not thrown.
async function send(to: string, subject: string, html: string, text: string) {
  const from = process.env.POSTMARK_FROM_EMAIL;
  if (!from || !process.env.POSTMARK_SERVER_TOKEN) {
    console.warn(`[email] Postmark not configured; skipping "${subject}"`);
    return;
  }
  try {
    await getPostmark().sendEmail({
      From: from,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: "outbound",
    });
  } catch (err) {
    console.error(`[email] failed to send "${subject}"`, err);
  }
}

export async function sendWelcomeEmail({ email, name }: Recipient) {
  const url = `${appUrl()}/dashboard`;
  await send(
    email,
    "Welcome to Notely",
    `<p>Hi ${escapeHtml(name)},</p><p>Welcome to Notely! <a href="${url}">Open your dashboard</a> to get started.</p>`,
    `Hi ${name},\n\nWelcome to Notely! Open your dashboard to get started: ${url}\n`,
  );
}

export async function sendPasswordResetEmail({ email, name }: Recipient, token: string) {
  const url = `${appUrl()}/reset-password?token=${encodeURIComponent(token)}`;
  await send(
    email,
    "Reset your Notely password",
    `<p>Hi ${escapeHtml(name)},</p><p><a href="${url}">Reset your password</a>. This link expires in 1 hour. If you didn't ask for this, ignore this email.</p>`,
    `Hi ${name},\n\nReset your password: ${url}\n\nThis link expires in 1 hour. If you didn't ask for this, ignore this email.\n`,
  );
}
EOF
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { createHash, randomBytes } from "node:crypto";\nimport { sendPasswordResetEmail, sendWelcomeEmail } from "@/lib/email";\n\n'+s
s+='''
export async function createUser(input: { email: string; name: string }): Promise<User> {
  const email = input.email.trim().toLowerCase();
  if (users.some((u) => u.email === email)) {
    throw new Error("A user with this email already exists");
  }
  const user: User = {
    id: String(users.length + 1),
    email,
    name: input.name.trim(),
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// Only the hash of each token is stored, so a leaked list can't be used to reset passwords.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();
const hashToken = (t: string) => createHash("sha256").update(t).digest("hex");

// Always resolves the same way whether or not the email exists, so callers can't probe for accounts.
export async function requestPasswordReset(email: string): Promise<void> {
  const normalized = email.trim().toLowerCase();
  const user = users.find((u) => u.email === normalized);
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  await sendPasswordResetEmail(user, token);
}

// Single-use: returns the user the token belongs to and invalidates it.
export async function consumePasswordResetToken(token: string): Promise<User | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return getUser(entry.userId);
}
'''
open(p,'w').write(s)
EOF
cat > .env.example <<'EOF'
# Postmark (https://postmarkapp.com) — Servers → API Tokens
POSTMARK_SERVER_TOKEN=server_token_placeholder
# Must be a confirmed sender signature or on a verified domain
POSTMARK_FROM_EMAIL=hello@example.com
# Base URL used in email links
APP_URL=http://localhost:3000
EOF
printf '!.env.example\n' >> .gitignore
sed -i '' 's/, no billing, and no email yet\./, and no billing. Transactional email (welcome, password reset) goes through Postmark; copy `.env.example` to `.env.local` and fill in the values./' README.md
npx tsc --noEmit && npm run lint 2>&1 | tail -5; git status --short

